script:
(function () {
  'use strict';
  // Composite APR for an adjustable-rate mortgage, on the basis Regulation Z sets for disclosures
  // (12 CFR 1026.17(c)(1) and Official Interpretation comment 17(c)(1)-10): the start rate is used for
  // as long as it applies, then the fully indexed rate (index value at consummation + margin), reached
  // only as fast as the first and periodic caps allow and never above the lifetime cap. The payment is
  // re-amortized over the months left at each change and rounded to the cent. The APR is 12 x the
  // monthly rate j that makes the payments worth exactly the amount financed (loan - prepaid finance
  // charges): A = sum P_k / (1 + j)^k, solved by bisection. Comment 22(a)(3): 1/4-point tolerance.
  // An optional index change per adjustment gives a second APR on the user's own rate path.
  // Verified in Node (scratchpad mtg6/tests/aapr.test.js) against the examples in comment
  //   17(c)(1)-10.v (read on eCFR this session): $100,000, 30 years, 9% for year 1, T-bill 10% + 2%:
  //   A. no caps -> 12 x $804.62 then $1,025.31, APR 11.632% (published 11.63%);
  //   B. 2% periodic cap -> $804.62 / $950.09 / $1,024.34, APR 11.527% (published 11.53%).
  //   Our finance charges ($266,451.29 and $265,229.06) are a few dollars below the published ones
  //   ($266,463.32 / $265,234.76) only because we true up the last payment to clear the balance.
  //   Also: start = fully indexed and no fees -> APR = note rate (12.0000%); 0% rates handled;
  //   blank, negative and fees >= loan show an error and never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // --- pure ---
  function payment(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  // Rate for each month and the resulting payment stream.
  // o: loan, months, start, fixedMonths, every, index, margin, idxChange, firstCap, perCap, lifeCap, floor
  function armSchedule(o) {
    var rate = o.start, bal = o.loan, pays = [], levels = [], adj = 0, pay = 0, interestTotal = 0;
    var ceiling = o.start + o.lifeCap;
    for (var m = 0; m < o.months; m++) {
      var changed = m === 0;
      if (m >= o.fixedMonths && (m - o.fixedMonths) % o.every === 0) {
        adj++;
        var target = o.index + o.idxChange * adj + o.margin;
        var cap = adj === 1 ? o.firstCap : o.perCap;
        target = Math.max(rate - cap, Math.min(rate + cap, target));
        target = Math.max(o.floor, Math.min(ceiling, target));
        target = Math.max(0, target);
        if (Math.abs(target - rate) > 1e-12) { rate = target; changed = true; }
      }
      if (changed) {
        pay = Math.round(payment(bal, rate, o.months - m) * 100) / 100;
        levels.push({ from: m + 1, count: 0, rate: rate, pay: pay });
      }
      var interest = bal * rate / 1200;
      var p = pay;
      if (m === o.months - 1 || p > bal + interest) p = Math.round((bal + interest) * 100) / 100;
      bal = bal + interest - p;
      if (Math.abs(bal) < 0.005) bal = 0;
      interestTotal += interest;
      pays.push(p);
      levels[levels.length - 1].count++;
    }
    // The trued-up last payment is shown as its own level only if it differs by more than a dollar.
    var last = levels[levels.length - 1];
    if (last.count > 1 && Math.abs(pays[pays.length - 1] - last.pay) > 1) {
      last.count--;
      levels.push({ from: o.months, count: 1, rate: last.rate, pay: pays[pays.length - 1], final: true });
    }
    return { pays: pays, levels: levels, total: pays.reduce(function (a, b) { return a + b; }, 0) };
  }

  function pvStream(pays, j) {
    var v = 0, d = 1;
    for (var k = 0; k < pays.length; k++) { d /= (1 + j); v += pays[k] * d; }
    return v;
  }

  // Monthly rate j with sum pays[k] / (1 + j)^(k+1) = net.
  function solveApr(net, pays) {
    var sum = pays.reduce(function (a, b) { return a + b; }, 0);
    if (net <= 0 || sum <= 0) return NaN;
    if (net >= sum - 1e-9) return 0;
    var lo = 0, hi = 0.05;
    while (pvStream(pays, hi) > net && hi < 100) hi *= 2;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (pvStream(pays, mid) > net) lo = mid; else hi = mid;
    }
    return 12 * (lo + hi) / 2;
  }
  // --- end pure ---

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function pct(v, d) { return (v).toFixed(d === undefined ? 3 : d) + '%'; }
  function cell(row, text) { var td = document.createElement('td'); td.textContent = text; row.appendChild(td); }

  var OUT = ['aaprApr', 'aaprPathApr', 'aaprFully', 'aaprFirstPay', 'aaprMaxPay', 'aaprCharge', 'aaprFinanced', 'aaprPrepaid', 'aaprTotal', 'aaprFixedApr', 'aaprGap', 'aaprNote'];
  function clearAll() {
    OUT.forEach(function (id) { setText(id, '–'); });
    el('aaprLevels').textContent = '';
  }

  function update() {
    var loan = read('aaprLoan', NaN), years = parseInt(el('aaprTerm').value, 10), start = read('aaprStart', NaN),
        fixedYears = parseInt(el('aaprFixed').value, 10), every = parseInt(el('aaprEvery').value, 10),
        index = read('aaprIndex', NaN), margin = read('aaprMargin', NaN),
        firstCap = read('aaprFirstCap', Infinity), perCap = read('aaprPerCap', Infinity), lifeCap = read('aaprLifeCap', Infinity),
        floor = read('aaprFloor', 0), points = read('aaprPoints', 0), orig = read('aaprOrig', 0), other = read('aaprOther', 0),
        idxChange = read('aaprIdxChange', 0);
    var msg = '';
    if (isNaN(loan) || loan <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(start) || start < 0 || start > 30) msg = 'Enter a start rate from 0% to 30%.';
    else if (isNaN(index) || index < 0 || index > 30 || isNaN(margin) || margin < 0 || margin > 15) msg = 'Enter an index from 0% to 30% and a margin from 0% to 15%.';
    else if ([firstCap, perCap, lifeCap, floor].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Caps and floor cannot be negative. Leave a cap blank if the loan has none.';
    else if ([points, orig, other].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Fees and points cannot be negative.';
    else if (points > 10 || orig > 10) msg = 'Enter 10 points or fewer and an origination fee of 10% or less.';
    else if (isNaN(idxChange) || Math.abs(idxChange) > 5) msg = 'Enter an index change per adjustment between -5% and 5%.';
    var months = years * 12, fixedMonths = fixedYears * 12;
    if (!msg && fixedMonths >= months) msg = 'The fixed-rate period must be shorter than the loan term.';
    var prepaid = loan * (points + orig) / 100 + other, net = loan - prepaid;
    if (!msg && net <= 0) msg = 'Prepaid finance charges must be less than the loan amount.';
    el('aaprError').hidden = !msg;
    el('aaprError').textContent = msg;
    if (msg) { clearAll(); return; }

    var base = { loan: loan, months: months, start: start, fixedMonths: fixedMonths, every: every, index: index, margin: margin,
                 idxChange: 0, firstCap: firstCap, perCap: perCap, lifeCap: lifeCap, floor: floor };
    var s = armSchedule(base);
    var apr = solveApr(net, s.pays);
    var pathO = Object.assign({}, base, { idxChange: idxChange });
    var sp = armSchedule(pathO);
    var pathApr = solveApr(net, sp.pays);
    var flat = armSchedule(Object.assign({}, base, { fixedMonths: months }));
    var fixedApr = solveApr(net, flat.pays);
    if ([apr, pathApr, fixedApr].some(isNaN)) { clearAll(); return; }

    var maxPay = 0;
    s.levels.forEach(function (l) { if (!l.final && l.pay > maxPay) maxPay = l.pay; });
    setText('aaprApr', pct(apr * 100));
    setText('aaprPathApr', idxChange === 0 ? 'Same as above (index unchanged)' : pct(pathApr * 100));
    setText('aaprFully', pct(index + margin));
    setText('aaprFirstPay', money.format(s.levels[0].pay));
    setText('aaprMaxPay', money.format(maxPay));
    setText('aaprCharge', money.format(s.total - net));
    setText('aaprFinanced', money.format(net));
    setText('aaprPrepaid', money.format(prepaid));
    setText('aaprTotal', money.format(s.total));
    setText('aaprFixedApr', pct(fixedApr * 100));
    var gap = apr * 100 - start;
    setText('aaprGap', (gap >= 0 ? '+' : '') + gap.toFixed(3) + ' percentage points');
    var fully = index + margin;
    var note;
    if (Math.abs(fully - start) < 1e-9) note = 'The start rate equals the fully indexed rate, so the rate never changes on the disclosure basis. The APR is above the note rate only because of the prepaid finance charges.';
    else if (fully > start) note = 'The start rate is ' + (fully - start).toFixed(3) + ' points below the fully indexed rate (a discounted start rate). The disclosed APR blends the low start rate with the higher rate that follows, so it sits well above the rate you pay at first.';
    else note = 'The start rate is above the fully indexed rate (a premium start rate). With the index unchanged the rate falls at the first adjustment, so the composite APR is pulled below the start rate before fees.';
    setText('aaprNote', note);

    var body = el('aaprLevels');
    body.textContent = '';
    s.levels.forEach(function (l) {
      var tr = document.createElement('tr');
      cell(tr, String(l.count));
      cell(tr, l.count === 1 ? String(l.from) : l.from + '–' + (l.from + l.count - 1));
      cell(tr, pct(l.rate));
      cell(tr, money.format(l.pay) + (l.final ? ' (final)' : ''));
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('aaprForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
